"03e0adb3-dbd2-4383-8e29-970cda6f4eea"}]}],"declaredType":"com.ibm.bpmsdk.model.coach.ContentBoxContrib","id":"5024391e-475a-4902-89e6-19aa59e5b5b1","contentBoxId":"ContentBox1"}],"layoutItemId":"Section1","id":"db7cf286-550d-336d-9d40-1c6a34e13630","configData":[{"optionName":"@label","value":"tw.local.activityName","declaredType":"com.ibm.bpmsdk.model.coach.ConfigData","id":"eb4c9ce2-2c33-3408-a811-3ca51d4f0121","valueType":"dynamic"},{"optionName":"@labelVisibility","value":"SHOW","declaredType":"com.ibm.bpmsdk.model.coach.ConfigData","id":"7a7c1bd4-06aa-3a53-8729-25844a4ac8ac"},{"optionName":"showBorder","value":"{"isResponsiveData":true,"values":[{"deviceConfigID":"LargeID","value":true}]}","declaredType":"com.ibm.bpmsdk.model.coach.ConfigData","id":"b883f87d-38e2-3875-9f30-472c54b842bb"}]}]}}},"isForCompensation":false,"id":"2025.32f285f1-5934-4054-ae8e-b99a6efa3bb8","name":"Display Task Details","outgoing":["2027.b8c73866-fbc8-48c9-83f0-b3930b6d77ab","2027.d2d078e9-dc5e-4548-a5b7-57c979c61d07"],"startQuantity":1},{"scriptFormat":"text/x-javascript","declaredType":"scriptTask","extensionElements":{"nodeVisualInfo":[{"declaredType":"TNodeVisualInfo","width":95,"height":70,"x":206,"y":177}]},"incoming":["2027.8eeb50a7-14f4-4c1a-b9a6-f9734b583614"],"completionQuantity":1,"isForCompensation":false,"documentation":[{"textFormat":"text/plain","content":["Get Task Details"]}],"id":"2025.5c7f9efd-1aef-43ea-ab2c-5bf052d66826","name":"Get Task Details","script":{"content":["tw.local.defaultText = "This is a sample coach for the following activity: ";
tw.local.activityName = "Default Responsive Human Service";
if (!!tw.system.processInstance) {
var task = tw.system.processInstance.task;
if (!!task) {
tw.local.taskId = task.id;
tw.local.subject = task.subject;
tw.local.userName = task.owner;
tw.local.taskNarrative = task.narrative;
if (!!task.processActivityName)
tw.local.activityName = task.processActivityName;
if (!!task.processActivityDescription)
tw.local.activityDescription = task.processActivityDescription;
var instance = tw.system.processInstance;
if (!!instance) {
var process = instance.process;
tw.local.bpdInstanceId = instance.id;
tw.local.bpdInstanceName = instance.name;
tw.local.bpdName = process.name;
tw.local.bpdDescription = process.description;
}
}
}
